import numpy as np
A=np.array(grid)
out=np.ones_like(A)
for col in [2,6]:
 seen=set()
 for r in range(A.shape[0]):
  for c in range(A.shape[1]):
   if A[r,c]!=col or (r,c) in seen: continue
   q=[(r,c)]; seen.add((r,c)); comp=[]
   while q:
    x,y=q.pop(); comp.append((x,y))
    for p in [(x+1,y),(x-1,y),(x,y+1),(x,y-1)]:
     if 0<=p[0]<A.shape[0] and 0<=p[1]<A.shape[1] and A[p]==col and p not in seen:
      seen.add(p); q.append(p)
   rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
   out[min(rs):max(rs)+1,min(cs):max(cs)+1]=col
print('\n'.join(' '.join(map(str,row)) for row in out.tolist()))

